Path registrationPath(List<int> runs) {
  final path = Path();
  for (var i = 0; i < runs.length; i += 4) {
    path.addRect(Rect.fromLTWH(runs[i].toDouble(), runs[i + 1].toDouble(),
        runs[i + 2].toDouble(), runs[i + 3].toDouble()));
  }
  return path;
}

List<int> _runs(String encoded) {
  final bytes = base64Decode(encoded);
  final data = ByteData.sublistView(bytes);
  return List<int>.generate(
      bytes.length ~/ 2, (i) => data.getUint16(i * 2, Endian.little),
      growable: false);
}

